def validate_runtime_catalog(catalog: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(catalog, dict):
        raise ContractError('metadata_dependency_error', 'metadata_compile', 'runtime catalog가 object가 아닙니다.')
