class GoodocsSourceRetriever(Component):
    display_name = "15 Goodocs 데이터 조회"
    description = "Goodocs 전용 작업과 검토된 문서 결과를 받아 메타데이터 물리 컬럼 계약으로 검증합니다."
    icon = "database"
    metadata = {"logical_stage": "goodocs_retrieval", "source_type": "goodocs"}
    inputs = [
        DataInput(name="job_bundle", display_name="Goodocs 조회 작업", required=True, info="라우터가 Goodocs에만 배정한 최소 조회 작업입니다."),
        DataInput(name="domain_bundle", display_name="사용 가능 메타데이터", required=True, info="조회 행의 데이터셋·필드 계약을 검증할 현재 메타데이터입니다."),
        NestedDictInput(
            name="source_payload",
            display_name="Goodocs 조회 결과 행",
            value={},
            required=False,
            info="검토된 Goodocs 연동 코드가 query_ref/config_ref에 따라 반환한 데이터셋별 행입니다. 비밀값이나 연결 문자열을 넣지 않습니다.",
        ),
        IntInput(name="source_row_limit", display_name="조회 행 수 제한", value=50000, info="이 원천 노드가 한 번에 수신할 수 있는 최대 행 수입니다."),
    ]
    outputs = [Output(name="goodocs_results", display_name="Goodocs 원천 조회 결과", method="retrieve", types=["Data"])]

    def retrieve(self) -> Data:
        jobs = _payload(getattr(self, "job_bundle", None))
        lane = {
            "contract_version": PIPELINE_VERSION,
            "ok": True,
            "stage": "goodocs_retrieval",
            "lane": "goodocs",
            "status": "skipped",
            "source_results": [],
        }
        try:
            jobs = _require_context(jobs, "goodocs_retrieval")
            if not jobs.get("ok"):
                return Data(data=jobs)
            selected_jobs = list(jobs.get("jobs") or [])
            if jobs.get("data_mode") != "live" or not selected_jobs:
                return Data(data=lane)
            if str(jobs.get("source_type") or "") != "goodocs":
                raise ContractError("source_contract_error", "goodocs_retrieval", "라우터의 source type이 노드 역할과 일치하지 않습니다.")
            domain = _require_context(getattr(self, "domain_bundle", None), "goodocs_retrieval")
            if not domain.get("ok"):
                raise ContractError("metadata_dependency_error", "goodocs_retrieval", "사용 가능 메타데이터를 불러오지 못했습니다.")
            catalog = (domain.get("domain_bundle") or {}).get("runtime_catalog")
            payload = _payload(getattr(self, "source_payload", None))
            max_rows = max(1, min(int(getattr(self, "source_row_limit", 50000)), 100000))
            results = [
                _physical_result(job, _source_rows(payload, job, catalog, max_rows), "goodocs")
                for job in selected_jobs
            ]
            lane.update({"status": "selected", "source_results": results, "data_mode": "live"})
        except Exception as exc:
            lane = _pipeline_error(lane, exc, "goodocs_retrieval")
        return Data(data=lane)

